  !>  \brief Get ``rocblas_pointer_mode``.
  interface rocblas_get_pointer_mode
    function rocblas_get_pointer_mode_(handle,pointer_mode) bind(c, name="rocblas_get_pointer_mode")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_get_pointer_mode_
      type(c_ptr),value :: handle
      type(c_ptr),value :: pointer_mode
    end function
  end interface

  !>  \brief Set ``rocblas_atomics_mode``
  !>   \details
  !>   Some rocBLAS functions have implementations which use atomic operations to increase
  !>   performance.
  !>   By using atomic operations, results are not guaranteed to be identical between multiple runs.
  !>   Results are accurate with or without atomic operations. Atomic operations in rocBLAS are
  !>   turned
  !>   off by default. They can be turned on or off on a per-handle basis by calling
  !>   ``rocblas_set_atomics_mode``.
  interface rocblas_set_atomics_mode
    function rocblas_set_atomics_mode_(handle,atomics_mode) bind(c, name="rocblas_set_atomics_mode")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_set_atomics_mode_
      type(c_ptr),value :: handle
      integer(kind(rocblas_atomics_not_allowed)),value :: atomics_mode
    end function
  end interface

  !>  \brief Get ``rocblas_atomics_mode``.
  interface rocblas_get_atomics_mode
    function rocblas_get_atomics_mode_(handle,atomics_mode) bind(c, name="rocblas_get_atomics_mode")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_get_atomics_mode_
      type(c_ptr),value :: handle
      type(c_ptr),value :: atomics_mode
    end function
  end interface

  !>  \brief Set alpha stride for limited set of batched and strided_batched functions to specify
  !>  the stride for alpha between successive batch elements.
  !> Only applies to rocblas_pointer_mode_device and thus device side allocations.
  !> It enables interpretation of the alpha pointer for both batched and strided_batched functions
  !> as a pointer to a vector of values.
  !> Default value is 0 which treats it as a pointer to a single scalar. Support is denoted with
  !> specific function documentation.
  !> Warning this is a modal like state in the handle. Restore to value 0 if no longer applicable to
  !> later function calls.
  interface rocblas_set_batch_alpha_stride
    function rocblas_set_batch_alpha_stride_(handle,alpha_stride) &
        bind(c, name="rocblas_set_batch_alpha_stride")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_set_batch_alpha_stride_
      type(c_ptr),value :: handle
      integer(c_int64_t),value :: alpha_stride
    end function
  end interface

  !>  \brief Get batch alpha stride from the handle.
  interface rocblas_get_batch_alpha_stride
    function rocblas_get_batch_alpha_stride_(handle,alpha_stride) &
        bind(c, name="rocblas_get_batch_alpha_stride")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_get_batch_alpha_stride_
      type(c_ptr),value :: handle
      type(c_ptr),value :: alpha_stride
    end function
  end interface

  !>  \brief Set beta stride for limited set of batched and strided_batched functions to specify the
  !>  stride for beta between successive batch elements.
  !> Only applies to rocblas_pointer_mode_device and thus device side allocations.
  !> It enables interpretation of the beta pointer for both batched and strided_batched functions as
  !> a pointer to a vector of values.
  !> Default value is 0 which treats it as a pointer to a single scalar. Support is denoted with
  !> specific function documentation.
  !> Warning this is a modal like state in the handle. Restore to value 0 if no longer applicable to
  !> later function calls.
  interface rocblas_set_batch_beta_stride
    function rocblas_set_batch_beta_stride_(handle,beta_stride) &
        bind(c, name="rocblas_set_batch_beta_stride")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_set_batch_beta_stride_
      type(c_ptr),value :: handle
      integer(c_int64_t),value :: beta_stride
    end function
  end interface

  !>  \brief Get batch beta stride from the handle.
  interface rocblas_get_batch_beta_stride
    function rocblas_get_batch_beta_stride_(handle,beta_stride) &
        bind(c, name="rocblas_get_batch_beta_stride")
      use iso_c_binding
