        bind(c, name="rocblas_set_device_memory_size")
      use iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      integer(kind(rocblas_status_success)) :: rocblas_set_device_memory_size_
      type(c_ptr),value :: handle
      integer(c_size_t),value :: mySize
    end function
  end interface

